// ge - native-renderer probe (milestone 1, checkpoint 2).
//
// Counts calls to every Direct3D function named in native/d3d_functions.toml,
// per frame (a frame ends at each D3DDevice_Swap), and captures every shader
// the game compiles or creates. The hooks are generated by native/gen_probe.py
// into native/probe_hooks.toml and src/ge_native_probe_table.inc; they sit at
// each function's first instruction and do nothing unless ge_native_probe is
// on. Output goes to <exe>\logs\native_probe_<date>_<time>\:
//   counts.csv   frame,name,count        (one row per function called that frame)
//   frames.csv   per-frame summary (draws, vertices, indices, targets, queries...)
//   shaders.csv  one row per compile/create call, with the FNV-1a hash
//   shaders\     each distinct HLSL source (.hlsl) and shader blob (.bin), by hash
//   queries.csv  each D3DQuery_Issue call's query pointer, type and flags
//   microcode.csv every in-place shader registration (vertex/pixel), with its microcode hash
//   resolves.csv resolves and binds of resolved textures, on frame 0 and every 300th frame

#ifndef WIN32_LEAN_AND_MEAN
#define WIN32_LEAN_AND_MEAN
#endif
#ifndef NOMINMAX
#define NOMINMAX
#endif
#include <windows.h>

#include <atomic>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <mutex>
#include <string>
#include <unordered_map>
#include <unordered_set>
#include <vector>

#include "ge_init.h"   // PPCRegister
#include <rex/cvar.h>
#include <rex/hook.h>
#include <rex/system/kernel_state.h>
#include <rex/system/xmemory.h>

REXCVAR_DEFINE_BOOL(ge_native_probe, false, "Debug",
                    "Native-renderer probe: count D3D calls per frame and capture shaders "
                    "to logs\\native_probe_*\\ (research aid, slows the game)");

namespace {

struct NpFn {
  uint32_t address;
  const char* name;
};

std::atomic<bool> g_np_on{false};

inline uint8_t* guest_base() {
  return rex::system::kernel_state()->memory()->virtual_membase();
}

inline uint32_t be32(uint32_t v) { return __builtin_bswap32(v); }

// Guest reads that may run off a mapped page: copy under SEH so a bad length
// or pointer costs one capture, not the game.
bool safe_copy(void* dst, uint32_t guest, size_t n) {
  if (!guest) return false;
  const uint8_t* src = guest_base() + guest;
  __try {
    std::memcpy(dst, src, n);
  } __except (EXCEPTION_EXECUTE_HANDLER) {
    return false;
  }
  return true;
}

uint32_t guest_u32(uint32_t guest) {
  uint32_t v = 0;
  return safe_copy(&v, guest, 4) ? be32(v) : 0;
}

std::string guest_cstr(uint32_t guest) {
  char buf[65] = {};
  for (int i = 0; i < 64; ++i) {
    if (!safe_copy(&buf[i], guest + i, 1) || buf[i] == 0) break;
  }
  return std::string(buf);
}

uint64_t fnv1a(const uint8_t* p, size_t n) {
  uint64_t h = 0xCBF29CE484222325ull;
  for (size_t i = 0; i < n; ++i) { h ^= p[i]; h *= 0x100000001B3ull; }
  return h;
}

}  // namespace

static void ge_np_hit(uint32_t idx);
static void ge_np_frame(uint32_t idx);
static void ge_np_draw(uint32_t idx, uint32_t prim, uint32_t count, bool indexed);
static void ge_np_compile(uint32_t idx, uint32_t src, uint32_t len, uint32_t entry, uint32_t profile);
static void ge_np_create_shader(uint32_t idx, uint32_t blob, bool pixel);
static void ge_np_inplace_shader(uint32_t idx, uint32_t header, uint32_t data);
static void ge_np_bind_shader(uint32_t idx, uint32_t shader, bool vertex);
static void ge_np_query(uint32_t idx, uint32_t query, uint32_t flags);
static void ge_np_target(uint32_t idx, uint32_t slot, uint32_t surface);
static void ge_np_resolve(uint32_t idx, uint32_t flags, uint32_t src_rect, uint32_t dest,
                          uint32_t dest_point, uint32_t level, uint32_t slice);
static void ge_np_set_texture(uint32_t idx, uint32_t device, uint32_t sampler, uint32_t texture);
static void ge_np_tiling(uint32_t idx, uint32_t tiles);

#include "ge_native_probe_table.inc"

namespace {

std::atomic<uint32_t> g_counts[kNpCount];

// Per-frame extras, all reset at each Swap.
std::atomic<uint32_t> g_draws{0}, g_draws_indexed{0}, g_vertices{0}, g_indices{0};
std::atomic<uint32_t> g_prims[8];  // by D3DPRIMITIVETYPE 1..7 (0 = other)
std::atomic<uint32_t> g_rt_sets{0}, g_ds_sets{0}, g_resolves{0}, g_tiles{0};
std::atomic<uint32_t> g_q_begin{0}, g_q_end{0}, g_shader_events{0};

std::mutex g_io;
FILE* g_counts_csv = nullptr;
FILE* g_frames_csv = nullptr;
FILE* g_shaders_csv = nullptr;
FILE* g_queries_csv = nullptr;
std::wstring g_dir;
uint64_t g_frame = 0;
std::chrono::steady_clock::time_point g_last;
std::unordered_set<uint64_t> g_saved_shaders;
std::unordered_set<uint32_t> g_seen_queries;
std::unordered_map<uint32_t, bool> g_pending_shaders;  // in-place shader object -> vertex?
std::atomic<uint32_t> g_pending_count{0};
FILE* g_microcode_csv = nullptr;
FILE* g_resolves_csv = nullptr;
// Resolve map: logged in full on sample frames only (frame 0 and every 300th).
bool g_sample_frame = true;
uint32_t g_resolve_seq = 0;
std::unordered_set<uint32_t> g_resolved_textures;  // destinations resolved this sample frame

// Length in dwords of a Xenos shader program, from its control-flow block:
// CF instructions come in pairs packed into 3 dwords at the start; every exec
// names an address and count in 3-dword instruction slots, so the program ends
// at the furthest exec's address + count. Returns 0 if it doesn't parse.
uint32_t microcode_dwords(uint32_t guest) {
  uint32_t min_addr = 4096, max_end = 0;
  bool seen_end = false;
  for (uint32_t slot = 0; slot < 512 && slot < min_addr; ++slot) {
    uint32_t w[3];
    if (!safe_copy(w, guest + slot * 12, 12)) return 0;
    for (auto& x : w) x = be32(x);
    const uint64_t cf[2] = {w[0] | (static_cast<uint64_t>(w[1] & 0xFFFF) << 32),
                            (w[1] >> 16) | (static_cast<uint64_t>(w[2]) << 16)};
    for (uint64_t x : cf) {
      const uint32_t op = static_cast<uint32_t>(x >> 44) & 0xF;
      const bool exec = (op >= 1 && op <= 6) || op == 13 || op == 14;
      if (!exec) continue;
      const uint32_t addr = static_cast<uint32_t>(x) & 0xFFF;
      const uint32_t count = static_cast<uint32_t>(x >> 12) & 0x7;
      if (addr < min_addr) min_addr = addr;
      if (addr + count > max_end) max_end = addr + count;
      if (op == 2 || op == 4 || op == 6 || op == 14) seen_end = true;
    }
  }
  if (!seen_end || max_end == 0 || max_end > 1024 || min_addr == 0) return 0;
  return max_end * 3;
}

std::wstring exe_dir() {
  wchar_t path[MAX_PATH];
  const DWORD n = GetModuleFileNameW(nullptr, path, MAX_PATH);
  std::wstring s(path, path + n);
  const size_t slash = s.find_last_of(L"\\/");
  return slash == std::wstring::npos ? L"." : s.substr(0, slash);
}

FILE* open_csv(const wchar_t* name, const char* header) {
  FILE* f = _wfopen((g_dir + L"\\" + name).c_str(), L"wb");
  if (f) std::fprintf(f, "%s\n", header);
  return f;
}

// Called with g_io held.
bool ensure_open() {
  if (g_counts_csv) return true;
  SYSTEMTIME t;
  GetLocalTime(&t);
  wchar_t stamp[32];
  swprintf(stamp, 32, L"%04u%02u%02u_%02u%02u%02u", t.wYear, t.wMonth, t.wDay, t.wHour,
           t.wMinute, t.wSecond);
  const std::wstring logs = exe_dir() + L"\\logs";
  CreateDirectoryW(logs.c_str(), nullptr);
  g_dir = logs + L"\\native_probe_" + stamp;
  CreateDirectoryW(g_dir.c_str(), nullptr);
  CreateDirectoryW((g_dir + L"\\shaders").c_str(), nullptr);
  g_counts_csv = open_csv(L"counts.csv", "frame,name,count");
  g_frames_csv = open_csv(L"frames.csv",
                          "frame,ms,draws,draws_indexed,vertices,indices,pointlist,linelist,"
                          "linestrip,trilist,trifan,tristrip,rectlist_or_other,rt_sets,ds_sets,"
                          "resolves,tiles,query_begin,query_end,shader_events");
  g_shaders_csv = open_csv(L"shaders.csv", "frame,event,profile,entry,hash,bytes,detail");
  g_queries_csv = open_csv(L"queries.csv", "frame,query,type,flags,first_seen");
  g_microcode_csv = open_csv(L"microcode.csv",
                             "frame,kind,header,physical,container_flags,virtual_size,physical_size,hash,first_seen,method");
  g_resolves_csv = open_csv(L"resolves.csv",
                            "frame,seq,event,flags_or_sampler,texture,src_rect_or_device,dest_point,"
                            "level,slice,fetch0,fetch1,fetch2,fetch3,fetch4,fetch5");
  g_last = std::chrono::steady_clock::now();
  REXKRNL_INFO("GENATIVE probe writing to {}", std::string(g_dir.begin(), g_dir.end()));
  return g_counts_csv != nullptr;
}

void save_shader(uint64_t hash, const char* ext, const uint8_t* data, size_t n) {
  if (!g_saved_shaders.insert(hash ^ (ext[0] == 'h' ? 1 : 0)).second) return;
  wchar_t name[48];
  swprintf(name, 48, L"\\shaders\\%016llX.%hs", static_cast<unsigned long long>(hash), ext);
  if (FILE* f = _wfopen((g_dir + name).c_str(), L"wb")) {
    std::fwrite(data, 1, n, f);
    std::fclose(f);
  }
}

}  // namespace

static void ge_np_hit(uint32_t idx) {
  if (g_np_on.load(std::memory_order_relaxed))
    g_counts[idx].fetch_add(1, std::memory_order_relaxed);
}

static void ge_np_frame(uint32_t idx) {
  const bool on = REXCVAR_GET(ge_native_probe);
  g_np_on.store(on, std::memory_order_relaxed);
  if (!on) return;
  g_counts[idx].fetch_add(1, std::memory_order_relaxed);

  std::lock_guard<std::mutex> lock(g_io);
  if (!ensure_open()) return;
  const auto now = std::chrono::steady_clock::now();
  const double ms = std::chrono::duration<double, std::milli>(now - g_last).count();
  g_last = now;
  for (uint32_t i = 0; i < kNpCount; ++i) {
    const uint32_t c = g_counts[i].exchange(0, std::memory_order_relaxed);
    if (c) std::fprintf(g_counts_csv, "%llu,%s,%u\n", static_cast<unsigned long long>(g_frame),
                        kNpFns[i].name, c);
  }
  uint32_t prims[8];
  for (int i = 0; i < 8; ++i) prims[i] = g_prims[i].exchange(0, std::memory_order_relaxed);
  std::fprintf(g_frames_csv, "%llu,%.3f,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u\n",
               static_cast<unsigned long long>(g_frame), ms, g_draws.exchange(0),
               g_draws_indexed.exchange(0), g_vertices.exchange(0), g_indices.exchange(0),
               prims[1], prims[2], prims[3], prims[4], prims[5], prims[6], prims[0] + prims[7],
               g_rt_sets.exchange(0), g_ds_sets.exchange(0), g_resolves.exchange(0),
               g_tiles.exchange(0), g_q_begin.exchange(0), g_q_end.exchange(0),
               g_shader_events.exchange(0));
  ++g_frame;
  g_sample_frame = (g_frame % 300) == 0;
  g_resolve_seq = 0;
  g_resolved_textures.clear();
  if ((g_frame % 60) == 0) {
    std::fflush(g_counts_csv);
    std::fflush(g_frames_csv);
    std::fflush(g_shaders_csv);
    std::fflush(g_queries_csv);
    std::fflush(g_microcode_csv);
    std::fflush(g_resolves_csv);
  }
}

static void ge_np_draw(uint32_t idx, uint32_t prim, uint32_t count, bool indexed) {
  if (!g_np_on.load(std::memory_order_relaxed)) return;
  g_counts[idx].fetch_add(1, std::memory_order_relaxed);
  g_draws.fetch_add(1, std::memory_order_relaxed);
  if (indexed) {
    g_draws_indexed.fetch_add(1, std::memory_order_relaxed);
    g_indices.fetch_add(count, std::memory_order_relaxed);
  } else {
    g_vertices.fetch_add(count, std::memory_order_relaxed);
  }
  g_prims[(prim >= 1 && prim <= 7) ? prim : 0].fetch_add(1, std::memory_order_relaxed);
}

// D3DXCompileShader(pSrcData, SrcDataLen, pDefines, pInclude, pFunctionName, pProfile, ...)
static void ge_np_compile(uint32_t idx, uint32_t src, uint32_t len, uint32_t entry,
                          uint32_t profile) {
  ge_np_hit(idx);
  if (!g_np_on.load(std::memory_order_relaxed)) return;
  g_shader_events.fetch_add(1, std::memory_order_relaxed);
  std::vector<uint8_t> text(len < (1u << 20) ? len : 0);
  const bool ok = !text.empty() && safe_copy(text.data(), src, text.size());
  const uint64_t hash = ok ? fnv1a(text.data(), text.size()) : 0;
  const std::string prof = guest_cstr(profile), fn = guest_cstr(entry);
  std::lock_guard<std::mutex> lock(g_io);
  if (!ensure_open()) return;
  if (ok) save_shader(hash, "hlsl", text.data(), text.size());
  std::fprintf(g_shaders_csv, "%llu,compile,%s,%s,%016llX,%u,%s\n",
               static_cast<unsigned long long>(g_frame), prof.c_str(), fn.c_str(),
               static_cast<unsigned long long>(hash), len, ok ? "" : "unreadable");
}

// D3DDevice_CreateVertexShader / CreatePixelShader(pFunction). The blob is the
// XDK shader container: header (flags, virtual size, physical size, ...), the
// virtual part, then the microcode. Saved as virtual + physical bytes; check
// the sizes against the dumps before relying on them.
static void ge_np_create_shader(uint32_t idx, uint32_t blob, bool pixel) {
  ge_np_hit(idx);
  if (!g_np_on.load(std::memory_order_relaxed)) return;
  g_shader_events.fetch_add(1, std::memory_order_relaxed);
  const uint32_t flags = guest_u32(blob), vsize = guest_u32(blob + 4),
                 psize = guest_u32(blob + 8);
  const uint64_t total = static_cast<uint64_t>(vsize) + psize;
  std::vector<uint8_t> data(total > 0 && total < (1u << 20) ? total : 0);
  const bool ok = !data.empty() && safe_copy(data.data(), blob, data.size());
  const uint64_t hash = ok ? fnv1a(data.data(), data.size()) : 0;
  char detail[96];
  std::snprintf(detail, sizeof(detail), "blob=%08X flags=%08X virtual=%u physical=%u%s", blob,
                flags, vsize, psize, ok ? "" : " unreadable");
  std::lock_guard<std::mutex> lock(g_io);
  if (!ensure_open()) return;
  if (ok) save_shader(hash, "bin", data.data(), data.size());
  std::fprintf(g_shaders_csv, "%llu,%s,,,%016llX,%llu,%s\n",
               static_cast<unsigned long long>(g_frame), pixel ? "create_ps" : "create_vs",
               static_cast<unsigned long long>(hash), static_cast<unsigned long long>(total),
               detail);
}

// Shaders the game builds in place from its level/asset files. In the CAFF
// data each shader is stored as [runtime object][XDK shader container]: the
// object is 872 bytes for a vertex shader (XGRegisterVertexShader's header,
// whose descriptor at +872 is the container) and 40 bytes for a pixel shader,
// so the container's virtual part sits at object+872 / object+40. The physical
// part (microcode) is NOT filled yet when the game registers the shader (the
// GPU data streams in afterwards), so registration only marks the object as
// pending, and the capture happens the first time the shader is bound
// (SetVertexShader / SetPixelShader), reading the physical pointer the
// registration stored (VS object +32, PS object +24).
// Saved once per hash as shaders\<hash>.vs.bin / .ps.bin = virtual part +
// physical part, the contiguous layout XenosRecomp scans for. If the container
// doesn't check out, the microcode alone is saved as .vs.phys / .ps.phys, its
// length taken from the control-flow block (tried at the physical start and +64).
// Called with g_io held.
static void capture_shader(uint32_t object, uint32_t data, bool vertex) {
  // Physical memory mapped at 0xE0000000+ is seen by the GPU 4 KB further on
  // than the same guest address reads here (the 0xE heap's physical offset);
  // reading at the raw pointer returned the data 4 KB before the microcode.
  if (data >= 0xE0000000u) data += 0x1000;
  const uint32_t container = object + (vertex ? 872 : 40);
  const uint32_t flags = guest_u32(container), vsize = guest_u32(container + 4),
                 psize = guest_u32(container + 8);
  std::vector<uint8_t> blob;
  const char* method = "container";
  if ((flags & 0xFFFFFF00u) == 0x102A1100u && vsize > 36 && vsize < 65536 && psize < 65536) {
    blob.resize(vsize + psize);
    if (!safe_copy(blob.data(), container, vsize) ||
        !safe_copy(blob.data() + vsize, data, psize))
      blob.clear();
  }
  if (blob.empty()) {
    method = "none";
    for (uint32_t off : {0u, 64u}) {
      if (const uint32_t n = microcode_dwords(data + off)) {
        blob.resize(off + n * 4);
        if (!safe_copy(blob.data(), data, blob.size())) blob.clear();
        method = off ? "cf@64" : "cf@0";
        break;
      }
    }
  }
  const uint64_t hash = blob.empty() ? 0 : fnv1a(blob.data(), blob.size());
  const bool whole = method[0] == 'c' && method[1] == 'o';
  bool first = false;
  if (!blob.empty()) {
    first = g_saved_shaders.count(hash) == 0;
    save_shader(hash, vertex ? (whole ? "vs.bin" : "vs.phys") : (whole ? "ps.bin" : "ps.phys"),
                blob.data(), blob.size());
  }
  std::fprintf(g_microcode_csv, "%llu,%s,%08X,%08X,%08X,%u,%u,%016llX,%d,%s\n",
               static_cast<unsigned long long>(g_frame), vertex ? "vs" : "ps", object, data,
               flags, vsize, psize, static_cast<unsigned long long>(hash), first ? 1 : 0,
               blob.empty() ? "unreadable" : method);
}

static void ge_np_inplace_shader(uint32_t idx, uint32_t header, uint32_t data) {
  ge_np_hit(idx);
  if (!g_np_on.load(std::memory_order_relaxed)) return;
  g_shader_events.fetch_add(1, std::memory_order_relaxed);
  const bool vertex = kNpFns[idx].address == 0x8218DFF8;
  std::lock_guard<std::mutex> lock(g_io);
  if (!ensure_open()) return;
  if (g_pending_shaders.insert_or_assign(header, vertex).second)
    g_pending_count.fetch_add(1, std::memory_order_relaxed);
  std::fprintf(g_microcode_csv, "%llu,%s,%08X,%08X,,,,,,registered\n",
               static_cast<unsigned long long>(g_frame), vertex ? "vs" : "ps", header, data);
}

static void ge_np_bind_shader(uint32_t idx, uint32_t shader, bool vertex) {
  ge_np_hit(idx);
  if (!g_np_on.load(std::memory_order_relaxed) || !shader ||
      g_pending_count.load(std::memory_order_relaxed) == 0)
    return;
  std::lock_guard<std::mutex> lock(g_io);
  const auto it = g_pending_shaders.find(shader);
  if (it == g_pending_shaders.end() || it->second != vertex || !ensure_open()) return;
  g_pending_shaders.erase(it);
  g_pending_count.fetch_sub(1, std::memory_order_relaxed);
  capture_shader(shader, guest_u32(shader + (vertex ? 32 : 24)), vertex);
}

// D3DQuery_Issue(pQuery, Flags): BEGIN = 2, END = 1. Type is at +4 (9 = occlusion).
static void ge_np_query(uint32_t idx, uint32_t query, uint32_t flags) {
  ge_np_hit(idx);
  if (!g_np_on.load(std::memory_order_relaxed)) return;
  if (flags & 2) g_q_begin.fetch_add(1, std::memory_order_relaxed);
  if (flags & 1) g_q_end.fetch_add(1, std::memory_order_relaxed);
  const uint32_t type = guest_u32(query + 4);
  std::lock_guard<std::mutex> lock(g_io);
  if (!ensure_open()) return;
  const bool first = g_seen_queries.insert(query).second;
  std::fprintf(g_queries_csv, "%llu,%08X,%u,%u,%d\n", static_cast<unsigned long long>(g_frame),
               query, type, flags, first ? 1 : 0);
}

static void ge_np_target(uint32_t idx, uint32_t slot, uint32_t surface) {
  ge_np_hit(idx);
  if (!g_np_on.load(std::memory_order_relaxed)) return;
  (void)surface;
  (slot >= 4 ? g_ds_sets : g_rt_sets).fetch_add(1, std::memory_order_relaxed);
}

// Resolve(flags, pSourceRect, pDestTexture, pDestPoint, DestLevel, DestSliceOrFace, ...).
// On sample frames every resolve is logged with the destination's fetch
// constant (format and size), and SetTexture logs when a texture resolved
// earlier in the same frame is bound, giving the resolve -> texture -> sampler map.
static void log_fetch_row(const char* event, uint32_t a, uint32_t texture, uint32_t b, uint32_t c,
                   uint32_t d, uint32_t e) {
  uint32_t fetch[6] = {};
  for (int i = 0; i < 6; ++i) fetch[i] = texture ? guest_u32(texture + 28 + i * 4) : 0;
  std::fprintf(g_resolves_csv, "%llu,%u,%s,%08X,%08X,%08X,%08X,%u,%u,%08X,%08X,%08X,%08X,%08X,%08X\n",
               static_cast<unsigned long long>(g_frame), g_resolve_seq++, event, a, texture, b, c,
               d, e, fetch[0], fetch[1], fetch[2], fetch[3], fetch[4], fetch[5]);
}

static void ge_np_resolve(uint32_t idx, uint32_t flags, uint32_t src_rect, uint32_t dest,
                          uint32_t dest_point, uint32_t level, uint32_t slice) {
  ge_np_hit(idx);
  if (!g_np_on.load(std::memory_order_relaxed)) return;
  g_resolves.fetch_add(1, std::memory_order_relaxed);
  std::lock_guard<std::mutex> lock(g_io);
  if (!g_sample_frame || !ensure_open()) return;
  if (dest) g_resolved_textures.insert(dest);
  log_fetch_row("resolve", flags, dest, src_rect, dest_point, level, slice);
}

static void ge_np_set_texture(uint32_t idx, uint32_t device, uint32_t sampler, uint32_t texture) {
  ge_np_hit(idx);
  if (!g_np_on.load(std::memory_order_relaxed) || !texture) return;
  std::lock_guard<std::mutex> lock(g_io);
  if (!g_sample_frame || !g_resolved_textures.count(texture) || !ensure_open()) return;
  // device +12684 / +12688 = current pixel / vertex shader, to tell who samples it.
  log_fetch_row("bind", sampler, texture, device, guest_u32(device + 12684),
                guest_u32(device + 12688), 0);
}

static void ge_np_tiling(uint32_t idx, uint32_t tiles) {
  ge_np_hit(idx);
  if (g_np_on.load(std::memory_order_relaxed)) g_tiles.fetch_add(tiles, std::memory_order_relaxed);
}
